import { describe, expect, test } from 'bun:test';
import { covers, FakeLlm } from '@agentic-ddd/testing';
import { OperatorRuntime, type UseCaseInstances } from '@agentic-ddd/runtime';
import { CreateTask } from '../application/create-task';
import { CompleteTask } from '../application/complete-task';
import { InMemoryTaskRepository } from '../infrastructure/in-memory-task.repository';
import { TaskOperator } from '../operators/task.operator';
import { TaskCreated, TaskCompleted } from '../domain/task.events';

describe('task-operator', () => {
  test(
    covers(
      ['criterion:0001/tools', 'operator:task-operator'],
      'conclui tarefa usando apenas create_task e complete_task e publica TaskCreated/TaskCompleted',
    ),
    async () => {
      const llm = new FakeLlm([
        {
          stopReason: 'tool_calls',
          content: [
            {
              type: 'tool_call',
              id: 'call-1',
              name: 'create_task',
              input: { task_id: 't1', title: '  Comprar leite  ' },
            },
          ],
        },
        {
          stopReason: 'tool_calls',
          content: [
            {
              type: 'tool_call',
              id: 'call-2',
              name: 'complete_task',
              input: { task_id: 't1' },
            },
          ],
        },
        {
          stopReason: 'end',
          content: [{ type: 'text', text: 'Tarefa t1 criada e concluída.' }],
        },
      ]);
      const tasks = new InMemoryTaskRepository();
      const runtime = new OperatorRuntime({
        llm,
        modules: [{ name: 'tasks', path: 'app' }],
      });
      const useCaseMap = new Map();
      useCaseMap.set(CreateTask, new CreateTask(tasks));
      useCaseMap.set(CompleteTask, new CompleteTask(tasks));
      const useCases: UseCaseInstances = useCaseMap;
      await runtime.register(TaskOperator, useCases);

      const published: unknown[] = [];
      const unsubscribe = runtime.eventBus.subscribe((event) => {
        published.push(event);
      });

      try {
        const result = await runtime.run('task-operator', {
          message: 'Crie a tarefa t1 e conclua em seguida.',
        });

        expect(result.status).toBe('completed');
        expect(result.output).toContain('concluída');
        expect(result.steps.flatMap((step) => step.tools.map((tool) => tool.call.name))).toEqual([
          'create_task',
          'complete_task',
        ]);
        expect(llm.requests).toHaveLength(3);
        for (const request of llm.requests) {
          expect(request.tools.map((tool) => tool.name)).toEqual([
            'complete_task',
            'create_task',
          ]);
        }

        expect(published).toHaveLength(2);
        expect(published[0]).toBeInstanceOf(TaskCreated);
        expect((published[0] as TaskCreated).payload).toEqual({
          taskId: 't1',
          title: 'Comprar leite',
        });
        expect(published[1]).toBeInstanceOf(TaskCompleted);
        expect((published[1] as TaskCompleted).payload).toEqual({ taskId: 't1' });
      } finally {
        unsubscribe();
      }
    },
  );
});
